/**
 * A bestiary row's Size, read off what the row already states.
 *
 * Entries declare it in prose — a "Size +5" racial trait, or "Size +8" in the
 * notes — so it is parsed rather than duplicated into a third place that could
 * disagree with the other two. Anything that never says is Size 0: a person,
 * a wolf, a goblin, which is what most of the book is.
 */
function sizeFor(r: Row): number {
  const stated = [
    ...(r.traits ?? []).map(([name]) => name),
    r.note ?? '',
  ].join(' ');
  const m = stated.match(/\bSize\s*([+\u2212-]?\d+)/i);
  if (!m) return 0;
  return Number(m[1].replace('\u2212', '-'));
}

function sheetFor(r: Row): SheetData {
  const sheet = swade.defaultSheet();
  const [agility, smarts, spirit, strength, vigor] = r.attrs;
  Object.assign(sheet, {
    concept: r.name, wildCard: r.wild, agility, smarts, spirit, strength, vigor,
    size: sizeFor(r),
    hp: r.hp, maxHp: r.hp, pace: r.pace ?? 6, bennies: r.wild ? 2 : 0,
    skills: r.skills.map(([name, die]) => ({ name, die, notes: '' })),
    attacks: r.attacks.map(([name, skill, damage, dtype, range, meta]) => ({
      name, skill, damage, dtype, range, notes: '',
      ...(meta?.save ? { save: meta.save, onSave: meta.onSave ?? 'negate', saveDc: 4 } : {}),
      ...(meta?.condition ? { condition: meta.condition } : {}),
      // A template is either measured in feet (cones) or in tiles beyond the
      // target (SWADE's Small/Medium/Large blasts). Requiring aoeSize dropped
      // every tile-based one on the floor: 21 attacks — every swarm, the
      // Lich's Blast, the War Mech's missiles, the dinosaur tail sweeps, and
      // all the vehicle guns — were declared as areas in the data and arrived
      // at the sheet as ordinary single-target attacks.
      ...(meta?.aoeShape && (meta.aoeSize || meta.aoeHexes)
        ? {
          aoeShape: meta.aoeShape,
          ...(meta.aoeSize ? { aoeSize: meta.aoeSize } : {}),
          ...(meta.aoeHexes ? { aoeHexes: meta.aoeHexes } : {}),
        }
        : {}),
      ...(meta?.ap ? { ap: meta.ap } : {}),
    })),
    armor: (r.armor ?? []).map(([name, armor, parryBonus]) => ({ name, armor, parryBonus, equipped: true, notes: '' })),
    ...(r.traits ? { racialTraits: r.traits.map(([name, toughnessBonus]) => ({ name, toughnessBonus, notes: '' })) } : {}),
    ...(r.edges ? { edges: r.edges.map((name) => ({ name, ...traitColumnsFor(name) })) } : {}),
    ...(r.hindrances ? { hindrances: r.hindrances.map(([name, severity]) => ({ name, severity, ...traitColumnsFor(name) })) } : {}),
    ...(r.gear ? { inventory: r.gear.map(([name, notes]) => ({ name, qty: 1, weight: 0, equipped: true, notes })) } : {}),
    ...(r.resist ? { resist: r.resist } : {}),
    ...(r.immune ? { immune: r.immune } : {}),
    notes: r.note ?? '',
  });
  return sheet;
}

/** An Edge/Hindrance's live modifier columns, looked up by name in the
 *  compendium — one source of truth for what a named trait actually does.
 *  Anything without a mechanical hook still gets the right column shape. */
function traitColumnsFor(name: string): SheetData {
  const entry = CONTENT_SWADE.find(
    (e) => (e.kind === 'edge' || e.kind === 'hindrance') && e.name.toLowerCase() === name.toLowerCase(),
  );
  const t = entry?.trait;
  return {
    bonusSkill: t?.bonusSkill ?? '',
    bonusAmt: t?.bonusAmt ?? 0,
    parryBonus: t?.parryBonus ?? 0,
    toughnessBonus: t?.toughnessBonus ?? 0,
    paceBonus: t?.paceBonus ?? 0,
    notes: entry?.subtitle ?? '',
  };
}

function parryOf(r: Row): number {
  const fighting = r.skills.find(([n]) => n === 'Fighting');
  const shields = (r.armor ?? []).reduce((sum, [, , p]) => sum + p, 0);
  return 2 + Math.floor(dieSides(fighting ? fighting[1] : '') / 2) + shields;
}

export const NPCS_SWADE: NpcEntry[] = ROWS.map((r) => ({
  id: slug('swade', r.name),
  system: 'swade',
  name: r.name,
  category: r.category,
  challenge: r.tier,
  challengeLabel: r.wild ? 'Wild Card' : 'Extra',
  ac: parryOf(r),
  hp: r.hp,
  sheet: sheetFor(r),
}));
